// Filter transaksi 7 hari terakhir (zona waktu Asia/Jakarta) dan siapkan ringkasan untuk AI
const rows = $input.all().map(i => i.json).filter(r => r && r['Tanggal'] !== undefined && r['Tanggal'] !== '');

const now = DateTime.now().setZone('Asia/Jakarta');
const dayNum = (y, m, d) => Math.floor(Date.UTC(y, m - 1, d) / 86400000);
const todayDay = dayNum(now.year, now.month, now.day);
const startDay = todayDay - 7; // 7 hari terakhir: dari H-7 sampai hari ini

// Parse tanggal: dd/mm/yyyy, yyyy-mm-dd, ISO, atau serial number Google Sheets
function parseDay(v) {
  if (typeof v === 'number') return Math.floor(v) + Math.floor(Date.UTC(1899, 11, 30) / 86400000);
  const s = String(v).trim();
  let m = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})/);
  if (m) return dayNum(+m[3], +m[2], +m[1]);
  m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return dayNum(+m[1], +m[2], +m[3]);
  const dt = DateTime.fromISO(s, { zone: 'Asia/Jakarta' });
  return dt.isValid ? dayNum(dt.year, dt.month, dt.day) : null;
}
const toNumber = (v) => {
  const n = parseInt(String(v ?? '').replace(/[^0-9\-]/g, ''), 10);
  return isNaN(n) ? 0 : n;
};
const rupiah = (n) => 'Rp ' + n.toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const fmtDay = (d) => DateTime.fromMillis(d * 86400000, { zone: 'utc' }).toFormat('dd/MM/yyyy');

const transaksi = rows
  .map(r => ({
    day: parseDay(r['Tanggal']),
    tanggal: String(r['Tanggal']),
    kategori: r['Kategori'] || '-',
    deskripsi: r['Deskripsi'] || '-',
    metode: r['Metode Pembayaran'] || '-',
    jumlah: toNumber(r['Jumlah (IDR)']),
    penerima: r['Penerima'] || '-',
  }))
  .filter(t => t.day !== null && t.day >= startDay && t.day <= todayDay)
  .sort((a, b) => a.day - b.day);

const total = transaksi.reduce((s, t) => s + t.jumlah, 0);
const perKategori = {};
transaksi.forEach(t => { perKategori[t.kategori] = (perKategori[t.kategori] || 0) + t.jumlah; });

const ringkasanTeks = transaksi
  .map(t => `- ${t.tanggal} | ${t.kategori} | ${t.deskripsi} | ${t.metode} | ${rupiah(t.jumlah)} | ${t.penerima}`)
  .join('\n');
const ringkasanKategori = Object.entries(perKategori)
  .sort((a, b) => b[1] - a[1])
  .map(([k, v]) => `- ${k}: ${rupiah(v)}`)
  .join('\n');

return [{
  json: {
    rentang: `${fmtDay(startDay)} s.d. ${fmtDay(todayDay)}`,
    jumlahTransaksi: transaksi.length,
    totalPengeluaran: total,
    totalFormat: rupiah(total),
    perKategori,
    ringkasanKategori,
    ringkasanTeks,
    transaksi,
  },
}];

